<div class="page-heading"><div><div class="eyebrow">Ruang pemohon</div><h1>Permohonan saya</h1><p>Pantau setiap UTTP dan unduh hasil yang sudah tersedia.</p></div><a class="button primary" href="<?= site_url('permohonan/baru') ?>">+ Ajukan layanan</a></div>
<?php if ($notifications): ?><section class="card notice-card"><h2>Kabar terbaru</h2><?php foreach ($notifications as $n): ?><div class="notice-row"><strong><?= e($n->title) ?></strong><span><?= e($n->message) ?></span><small><?= e($n->sent_at) ?></small></div><?php endforeach; ?></section><?php endif; ?>
<section class="section"><h2>Riwayat permohonan</h2><?php if (!$requests): ?><div class="card empty"><div class="icon">+</div><h3>Belum ada permohonan</h3><p>Mulai dengan mengajukan tera atau tera ulang UTTP.</p><a class="button primary" href="<?= site_url('permohonan/baru') ?>">Buat permohonan</a></div><?php else: ?><div class="list-grid"><?php foreach ($requests as $r): ?><a class="card request-card" href="<?= site_url('permohonan/' . $r->id) ?>"><div class="request-top"><strong><?= e($r->request_no) ?></strong><span class="badge <?= status_class($r->request_status) ?>"><?= e(status_label($r->request_status)) ?></span></div><div class="request-bottom"><span><?= $r->service_type === 'tera_ulang' ? 'Tera ulang' : 'Tera' ?> · <?= (int) $r->unit_count ?> unit</span><span><?= e(date('d M Y', strtotime($r->submitted_at))) ?> →</span></div></a><?php endforeach; ?></div><?php endif; ?></section>
